function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || '' || payload.query || '').trim();
  return { payload, message, chatId, rawText };
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const ctx = getTelegramContext(source);
const raw = ctx.rawText;
const text = normalize(raw);
const prefixes = ['doc doc', 'xem doc', 'noi dung doc', 'read doc'];
let body = raw;
for (const prefix of prefixes) {
  if (text.startsWith(prefix + ' ')) {
    body = raw.slice(prefix.length + 1).trim();
    break;
  }
}

const docId = source.docId || source.documentId || source.fileId || source.targetId || args.docId || args.documentId || args.fileId || source.payload?.docId || '';
const docName = cleanName(source.docName || source.fileName || source.title || args.docName || args.fileName || args.title || body);

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text,
    docId,
    docName,
    hasTarget: Boolean(docId || docName),
    response: (docId || docName) ? '' : '📖 <b>Doc Google Doc</b>\n\nVi du: <code>doc doc Project Plan</code>'
  }
}];

const source = $('Prepare Action').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
if (!rows.length) {
  return [{ json: { ...source, docId: '', response: 'Mia chưa tìm thấy Google Doc phù hợp.' } }];
}
const doc = rows[0];
return [{ json: { ...source, docId: doc.id || source.docId || '', docName: doc.name || source.docName || '', webViewLink: doc.webViewLink || '', mimeType: doc.mimeType || '' } }];

function collectText(node, out = []) {
  if (Array.isArray(node)) {
    node.forEach((item) => collectText(item, out));
    return out;
  }
  if (!node || typeof node !== 'object') return out;
  if (node.textRun && typeof node.textRun.content === 'string') out.push(node.textRun.content);
  Object.values(node).forEach((value) => collectText(value, out));
  return out;
}

const source = $('Prepare Action').item.json || {};
const doc = $input.item.json || {};
const docId = doc.documentId || source.docId || '';
const title = doc.title || source.docName || 'Không rõ tên';
const link = source.webViewLink || (docId ? `https://docs.google.com/document/d/${docId}/edit` : '');
const content = collectText(doc.body?.content || []).join('').replace(/\n{3,}/g, '\n\n').trim();
let preview = content.slice(0, 1000) || '(Tài liệu này đang trống.)';
const truncated = content.length > 1000;

let text = `Mia đọc được Google Doc "${title}".`;
if (link) text += `\nLink: ${link}`;
text += `\n\nXem trước:\n${preview}`;
if (truncated) text += '\n\nMia đã rút gọn nội dung để tiết kiệm ngữ cảnh.';

return [{
  json: {
    ok: true,
    tool: 'docs.read_doc',
    chatId: source.chatId || '',
    text: text.trim(),
    links: link ? [link] : [],
    result: { documentId: docId, title, preview },
    meta: { truncated, contentLength: content.length }
  }
}];

const source = $json || {};
const tool = source.tool || source.workflowKey || '';
const target =
  source.docName ||
  source.sheetName ||
  source.query ||
  source.fileName ||
  source.rawText ||
  source.text ||
  '';

let text = source.response || source.text || '';
if (!text) {
  text = target
    ? `Mia chưa tìm thấy tài liệu phù hợp với "${target}".`
    : 'Mia cần tên tài liệu hoặc bảng tính để đọc.';
}

return [{
  json: {
    ok: false,
    tool,
    chatId: source.chatId || '',
    text: String(text).trim(),
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false ? 'missing_target' : 'not_found'
    }
  }
}];
